function renderItems() {
    // 1. CAPTURA DE ELEMENTOS DA INTERFACE
    const grid = document.getElementById('gridItems'); // Onde os cards serão exibidos
    const search = document.getElementById('searchInput').value.toLowerCase(); // Texto digitado na busca (em minúsculo)
    const sort = document.getElementById('sortOption').value; // Opção de ordenação selecionada
    const clearAllBtn = document.getElementById('clearAllBtn'); // Botão de "Limpar Tudo"
    
    // 2. CONTROLE DO BOTÃO DE LIMPAR BUSCA
    // Se houver algo digitado na busca, mostra o botão "X", senão esconde
    document.getElementById('clearBtn').style.display = search ? 'block' : 'none';
    
    // 3. DEFINIÇÃO DA FONTE DE DADOS
    // Se estiver na aba "all", usa a lista completa. Se estiver em "fav", usa a lista de favoritos
    let data = currentTab === 'all' ? [...items] : [...favorites];

    // 4. LÓGICA DE FILTRO (PESQUISA)
    if(search) {
        data = data.filter(i => 
            i.name.toLowerCase().includes(search) ||   // Verifica se o nome contém o que foi digitado
            i.id.toString() === search ||              // Verifica se o ID é exatamente igual ao digitado
            i.id.toString().includes(search)           // Verifica se o ID contém os números digitados
        );
    }

    // 5. LÓGICA DE ORDENAÇÃO
    if(sort === 'alpha') {
        // Ordem alfabética (A-Z)
        data.sort((a, b) => a.name.localeCompare(b.name));
    } else {
        // Ordem de ID (Mais recentes/Maiores primeiro)
        data.sort((a, b) => b.id - a.id);
    }

    // 6. VISIBILIDADE DO BOTÃO "LIMPAR FAVORITOS"
    // Só aparece se estivermos na aba de favoritos e se houver algum item lá
    clearAllBtn.style.display = (currentTab === 'fav' && favorites.length > 0) ? 'block' : 'none';

    // 7. RENDERIZAÇÃO NO HTML
    // Transforma o array de dados em uma sequência de blocos HTML (Cards)
    grid.innerHTML = data.map(item => `
        <div class="card" onclick="openModal(${item.id})">
            ${/* Se for aba de favoritos, adiciona o ícone de lixeira para remover */
              currentTab === 'fav' ? `<i class="fas fa-trash-can delete-fav" onclick="event.stopPropagation(); removeFavorite(${item.id})"></i>` : ''
            }
            <strong>${item.name}</strong>
            <span>ID: ${item.id}</span>
        </div>
    `).join(''); // O join('') remove as vírgulas entre os itens do array na tela
}

