let deferredPrompt;
window.addEventListener('beforeinstallprompt', (e) => {
    // Impede que o navegador mostre o banner automático muito rápido
    e.preventDefault();
    deferredPrompt = e;
    
    // Opcional: Mostrar um botão personalizado "Instalar App" no seu site
    console.log("O site pode ser instalado na tela inicial!");
});

// Exemplo de função para chamar a instalação (pode colocar num botão)
function installApp() {
    if (deferredPrompt) {
        deferredPrompt.prompt();
        deferredPrompt.userChoice.then((choiceResult) => {
            if (choiceResult.outcome === 'accepted') {
                console.log('Usuário aceitou a instalação');
            }
            deferredPrompt = null;
        });
    } else {
        alert("Para instalar, clique nos três pontinhos do navegador e selecione 'Adicionar à tela inicial'.");
    }
}
