///sistam de anticopia

const CONFIG_PROTECAO = {
    bloquearCliqueDireito: true,   // <-- Mude para false para liberar o mouse
    bloquearTeclado:       true,   // <-- Mude para false para liberar F12, Ctrl+U, etc
    bloquearSelecao:       true,   // <-- Mude para false para permitir copiar texto
    mostrarAlertas:        true    // <-- Mude para false para silenciar os avisos
};

/**
 * =========================================================
 * LÓGICA DO SISTEMA
 * =========================================================
 */
(function() {
    "use strict";

    // --- 1. Lógica do Clique Direito ---
    document.addEventListener('contextmenu', (event) => {
        if (CONFIG_PROTECAO.bloquearCliqueDireito) {
            event.preventDefault();
        }
    });

    // --- 2. Lógica do Teclado ---
    document.addEventListener('keydown', (event) => {
        // Se a proteção de teclado estiver desativada (false), sai da função
        if (!CONFIG_PROTECAO.bloquearTeclado) return;

        const key = event.key.toLowerCase();
        const ctrl = event.ctrlKey || event.metaKey;
        const shift = event.shiftKey;

        // Bloqueio de F12
        if (event.key === 'F12') {
            event.preventDefault();
            return false;
        }

        // Bloqueio de Ctrl+U (Ver código fonte)
        if (ctrl && key === 'u') {
            event.preventDefault();
            return false;
        }

        // Bloqueio de Ferramentas de Inspeção (Ctrl+Shift+I, J, C)
        if (ctrl && shift && (key === 'i' || key === 'j' || key === 'c')) {
            event.preventDefault();
            return false;
        }

        // Bloqueio de Cópia (Ctrl+C e Ctrl+X)
        if (ctrl && (key === 'c' || key === 'x')) {
            event.preventDefault();
            if (CONFIG_PROTECAO.mostrarAlertas) {
                alert("A cópia de conteúdo foi desativada.");
            }
            return false;
        }
    });

    // --- 3. Lógica de Seleção de Texto ---
    document.onselectstart = () => {
        // Se estiver como true, retorna false (bloqueia), se não, retorna true (libera)
        return !CONFIG_PROTECAO.bloquearSelecao;
    };

})();
