///bloqueio de botão 
(function() {
    // --- CONFIGURAÇÃO: ADICIONE OS IDS DOS BOTÕES AQUI ---
    const idsBloqueados = ['ID AQUI'];

    // 1. Criar o CSS da Mensagem Customizada via JS (Adaptado para classes)
    const style = document.createElement('style');
    style.textContent = `
        /* Classe aplicada a qualquer botão da lista */
        .status-bloqueado {
            cursor: not-allowed !important;
            opacity: 0.5 !important;
            filter: grayscale(1) !important;
        }

        /* Container da Mensagem (Overlay) */
        .msg-overlay {
            position: fixed;
            top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(0,0,0,0.7);
            display: flex; justify-content: center; align-items: center;
            z-index: 10000;
            font-family: sans-serif;
        }

        /* Caixa de Alerta */
        .msg-box {
            background: #fff;
            padding: 25px;
            border-radius: 8px;
            text-align: center;
            box-shadow: 0 10px 25px rgba(0,0,0,0.3);
            max-width: 300px;
            border-top: 5px solid #ff4444;
            animation: popIn 0.3s ease;
        }

        .msg-box h3 { color: #ff4444; margin: 0 0 10px; }
        .msg-box p { color: #333; margin-bottom: 20px; }

        .msg-btn {
            background: #ff4444;
            color: white; /* Corrigido de #white para white */
            border: none;
            padding: 10px 20px;
            border-radius: 5px;
            cursor: pointer;
            font-weight: bold;
        }

        @keyframes popIn {
            from { transform: scale(0.8); opacity: 0; }
            to { transform: scale(1); opacity: 1; }
        }
    `;
    document.head.appendChild(style);

    // 2. Função para criar a mensagem na tela (Dinâmica)
    const mostrarAviso = (nomeElemento) => {
        const overlay = document.createElement('div');
        overlay.className = 'msg-overlay';
        
        overlay.innerHTML = `
            <div class="msg-box">
                <h3>Acesso Negado</h3>
                <p>O recurso <strong>'${nomeElemento}'</strong> está temporariamente desativado por melhorias.</p>
                <button class="msg-btn" id="fecharMsg">Entendido</button>
            </div>
        `;
        
        document.body.appendChild(overlay);
document.getElementById('fecharMsg').onclick = () => overlay.remove();
    };

    // 3. Aplicar o bloqueio em todos os botões da lista
    idsBloqueados.forEach(id => {
        const btn = document.getElementById(id);
        
        if (btn) {
            // Aplica o visual de bloqueio
            btn.classList.add('status-bloqueado');
            
            // Remove o onclick original
            btn.onclick = null; 

            // Adiciona o evento de clique bloqueado
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopImmediatePropagation();
                
                // Pega o texto do botão ou o ID para a mensagem
                const textoBtn = btn.innerText || id;
                mostrarAviso(textoBtn);
            }, true);
        }
    });
})();
/**
 * SISTEMA INDEPENDENTE PARA FECHAMENTO DE MODAIS
 */
(function() {
    "use strict";

    // 1. Injetar CSS para animação de saída (opcional, para ficar suave)
    const style = document.createElement('style');
    style.textContent = `
        .fade-out {
            opacity: 0 !important;
            transition: opacity 0.3s ease;
            pointer-events: none;
        }
    `;
    document.head.appendChild(style);

    // 2. Função principal de fechamento
    const fecharSistemaModal = (elementoModal) => {
        if (!elementoModal) return;

        // Adiciona efeito de sumiço
        elementoModal.classList.add('fade-out');

        // Remove do HTML após a animação terminar (300ms)
        setTimeout(() => {
            elementoModal.remove();
        }, 300);
    };

    // 3. Ouvinte Global de Cliques (Delegação)
    document.addEventListener('click', (event) => {
        const target = event.target;

        // Caso A: Clicou no botão de fechar (ID ou Classe específica)
        if (target.id === 'fecharMsg' || target.classList.contains('msg-btn')) {
            const modal = target.closest('.msg-overlay');
            fecharSistemaModal(modal);
        }

        // Caso B: Clicou no fundo escuro (Overlay) e não na caixa branca
        if (target.classList.contains('msg-overlay')) {
            fecharSistemaModal(target);
        }
    });

    // 4. Fechar ao apertar a tecla "ESC"
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            const modalAberto = document.querySelector('.msg-overlay');
            if (modalAberto) fecharSistemaModal(modalAberto);
        }
    });

})();
